'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStrides from '@stdlib/ndarray-base-strides';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import ndarraylike2scalar from '@stdlib/ndarray-base-ndarraylike2scalar';
import { ndarray as strided } from '@stdlib/blas-base-dtrmv';


// MAIN //

/**
* Performs one of the matrix-vector operations `x = A*x` or `x = A^T*x`, where `x` is a one-dimensional ndarray and `A` is an `N` by `N` unit, or non-unit, upper or lower triangular matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a two-dimensional input ndarray corresponding to `A`.
*     -   a one-dimensional input/output ndarray corresponding to `x`.
*     -   a zero-dimensional ndarray specifying whether `A` is an upper or lower triangular matrix.
*     -   a zero-dimensional ndarray specifying whether `A` should be transposed, conjugate-transposed, or not transposed.
*     -   a zero-dimensional ndarray specifying whether `A` has a unit or non-unit diagonal.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float64Matrix from '@stdlib/ndarray-matrix-float64';
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import scalar2ndarray from '@stdlib/ndarray-from-scalar';
* import resolveTriangle from '@stdlib/blas-base-matrix-triangle-resolve-enum';
* import resolveTranspose from '@stdlib/blas-base-transpose-operation-resolve-enum';
* import resolveDiagonal from '@stdlib/blas-base-diagonal-type-resolve-enum';
*
* var A = new Float64Matrix( [ [ 1.0, 2.0, 3.0 ], [ 0.0, 1.0, 2.0 ], [ 0.0, 0.0, 1.0 ] ] );
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
*
* var uplo = scalar2ndarray( resolveTriangle( 'upper' ), {
*     'dtype': 'int32'
* });
* var trans = scalar2ndarray( resolveTranspose( 'no-transpose' ), {
*     'dtype': 'int32'
* });
* var diag = scalar2ndarray( resolveDiagonal( 'unit' ), {
*     'dtype': 'int32'
* });
*
* var z = dtrmv( [ A, x, uplo, trans, diag ] );
* // returns <ndarray>[ 14.0, 8.0, 3.0 ]
*
* var bool = ( z === x );
* // returns true
*/
function dtrmv( arrays ) {
	var trans;
	var uplo;
	var diag;
	var st;
	var A;
	var x;

	A = arrays[ 0 ];
	x = arrays[ 1 ];

	uplo = ndarraylike2scalar( arrays[ 2 ] );
	trans = ndarraylike2scalar( arrays[ 3 ] );
	diag = ndarraylike2scalar( arrays[ 4 ] );

	st = getStrides( A, false );

	strided( uplo, trans, diag, numelDimension( A, 0 ), getData( A ), st[ 0 ], st[ 1 ], getOffset( A ), getData( x ), getStride( x, 0 ), getOffset( x ) ); // eslint-disable-line max-len

	return x;
}


// EXPORTS //

export default dtrmv;
